export interface FirecrawlApi {
  scrape(url: string): Promise<ScrapeResult>;
  readonly mock: boolean;
}

export function createFirecrawl(cfg: AgentConfig): FirecrawlApi {
  if (cfg.mode === "mock" || !cfg.firecrawlApiKey) {
    return {
      mock: true,
      scrape: async (url: string) => ({
        url,
        markdown: SCRAPE_FIXTURES[url] ?? "",
        fetchedAt: "2026-11-26T11:30:00.000Z",
        mock: true,
      }),
    };
  }
  return {
    mock: false,
    scrape: async (url: string) => {
      const res = await fetch(`${cfg.firecrawlUrl}/scrape`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${cfg.firecrawlApiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ url, formats: ["markdown"] }),
      });
      if (!res.ok) throw new Error(`firecrawl scrape failed (${res.status}) for ${url}`);
      const body = (await res.json()) as { data?: { markdown?: string } };
      if (!body.data?.markdown) throw new Error(`firecrawl returned no markdown for ${url}`);
      return { url, markdown: body.data.markdown, fetchedAt: new Date().toISOString(), mock: false };
    },
  };
}
import { spawnSync } from "node:child_process";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { AnalysisResult, CompetitionMarket, EvidenceCandidate, ResearchSpec } from "../types.js";
import type { FirecrawlApi } from "../firecrawl/client.js";
import { factSignature } from "../evidence-log.js";
import { MOCK_NOW } from "../delphi/fixtures.js";

const MATHGEN = fileURLToPath(new URL("../../python/mathgen.py", import.meta.url));

/** Run python/mathgen.py for one analysis; returns stats + the CSV path written. */
export function runAnalysis(spec: ResearchSpec, csvPath: string, now: string): AnalysisResult {
  mkdirSync(dirname(csvPath), { recursive: true });
  const specPath = csvPath.replace(/\.csv$/, ".spec.json");
  writeFileSync(
    specPath,
    JSON.stringify({
      kind: spec.analysis.kind,
      params: spec.analysis.params,
      meta: { topic: spec.topic, market: spec.marketAddress, asOf: now },
    }),
    "utf-8",
  );
  const out = spawnSync("python3", [MATHGEN, "analyze", "--spec", specPath, "--csv", csvPath], {
    encoding: "utf-8",
  });
  if (out.error) throw out.error;
  if (out.status !== 0) {
    throw new Error(`mathgen failed for ${spec.topic} (exit ${out.status}): ${out.stderr}`);
  }
  rmSync(specPath, { force: true });
  return JSON.parse(out.stdout) as AnalysisResult;
}

export interface VerifyOutcome {
  ok: boolean;
  failures: { url: string; missing: string[] }[];
  warnings: string[];
}

/** Anti-`unverifiable`: every scraped link's content must still contain the
 *  figures we paste into the note. The judge fetches cited URLs with no JS,
 *  so claims must be present in static/markdown content. */
export async function verifySources(spec: ResearchSpec, firecrawl: FirecrawlApi): Promise<VerifyOutcome> {
  const failures: { url: string; missing: string[] }[] = [];
  const warnings: string[] = [];
  for (const link of spec.links) {
    if (link.access === "static-html" || !link.expect || link.expect.length === 0) continue;
    let markdown = "";
    try {
      markdown = (await firecrawl.scrape(link.url)).markdown;
    } catch (err) {
      failures.push({ url: link.url, missing: [`scrape failed: ${(err as Error).message}`] });
      continue;
    }
    if (markdown.trim() === "") {
      // Mock fixtures cover every scraped URL; an empty scrape means the fixture
      // or the live source is unreadable -> treat as unverifiable.
      failures.push({ url: link.url, missing: ["source content empty"] });
      continue;
    }
    const missing = link.expect.filter((needle) => !markdown.includes(needle));
    if (missing.length > 0) failures.push({ url: link.url, missing });
  }
  return { ok: failures.length === 0, failures, warnings };
}

/** Assemble the evidence-implied stance + signature into a candidate. */
export function assembleCandidate(
  spec: ResearchSpec,
  market: CompetitionMarket,
  analysis: AnalysisResult,
  now: string,
): EvidenceCandidate {
  const stance: "yes" | "no" = analysis.evidenceImpliedYes >= market.odds.yes ? "yes" : "no";
  return {
    marketAddress: market.address,
    marketQuestion: market.question,
    marketImpliedYes: market.odds.yes,
    topic: spec.topic,
    miningPath: spec.miningPath,
    langs: spec.langs,
    headline: spec.headline,
    figures: spec.figures,
    sourceDescriptions: spec.sourceDescriptions,
    links: spec.links.map(({ url, label, lang, access }) => ({ url, label, lang, access })),
    analysis,
    stance,
    factSignature: factSignature(market.address, spec.headline, spec.figures),
    asOf: now,
  };
}

/** For dedupe before mining: signature is computable from the spec alone. */
export function preSignature(spec: ResearchSpec): string {
  return factSignature(spec.marketAddress, spec.headline, spec.figures);
}

export const MOCK_AS_OF = MOCK_NOW;
import { resolveConfig } from "./config.js";
import { planPipeline, runPipeline } from "./pipeline.js";
import { SPECS_BY_MARKET } from "./miners/specs.js";

/**
 * CLI.
 *   npm run mock                 mock end-to-end run -> drafts under drafts/
 *   npm run live                 live run (needs DELPHI_API_ACCESS_KEY), drafts only
 *   npm run live -- --live-submit  live run; also POSTs drafts (further requires LIVE_SUBMIT=1)
 *   npm run plan                 no writes: eligibility + ranking table
 */

interface Args {
  mode?: "mock" | "live";
  liveSubmit: boolean;
  maxDrafts: number;
}

function parseArgs(argv: string[]): Args {
  const args: Args = { liveSubmit: false, maxDrafts: 10 };
  for (const a of argv) {
    if (a === "--mode=mock") args.mode = "mock";
    else if (a === "--mode=live") args.mode = "live";
    else if (a === "--live-submit") args.liveSubmit = true;
    else if (a.startsWith("--max-drafts=")) args.maxDrafts = Number(a.slice("--max-drafts=".length));
    else {
      console.error(`unknown argument: ${a}`);
      process.exit(2);
    }
  }
  return args;
}

async function main() {
  const [cmd, ...rest] = process.argv.slice(2);
  const args = parseArgs(rest);
  let cfg;
  try {
    cfg = resolveConfig(args);
  } catch (err) {
    console.error((err as Error).message);
    process.exit(1);
  }

  if (cmd === "run") {
    const report = await runPipeline(cfg, { maxDrafts: args.maxDrafts });
    console.log(`run complete (mode=${report.mode})`);
    console.log(`  markets seen:        ${report.marketsSeen}`);
    console.log(`  eligible:            ${report.marketsEligible}`);
    console.log(`  skipped by filter:   ${report.marketSkips.length}`);
    console.log(`  candidates mined:    ${report.candidatesMined}`);
    console.log(`  gate rejects:        ${report.gateRejects.length}`);
    for (const r of report.gateRejects) console.log(`     - ${r.topic}: ${r.reasons.join(" | ")}`);
    console.log(`  drafts written:      ${report.draftsWritten.length}`);
    for (const d of report.draftsWritten) console.log(`     - ${d}`);
    console.log(`  feedback drafts:     ${report.feedbackDrafts.length}`);
    if (cfg.liveSubmit) {
      console.log(
        "  NOTE: --live-submit was passed, but this build never POSTs drafts; " +
          "drafts sit under drafts/ with idempotency keys reserved in manifest.json.",
      );
    }
  } else if (cmd === "plan") {
    const report = await planPipeline(cfg);
    console.log(`plan (mode=${report.mode}, ${report.runTs})`);
    console.log(`markets seen: ${report.marketsSeen}, eligible: ${report.marketsEligible}`);
    for (const m of report.marketsConsidered) {
      const hasSpec = SPECS_BY_MARKET.has(m.address);
      console.log(
        `  eligible  cutoff=${m.evidenceCutoffAt} p(yes)=${m.odds.yes.toFixed(3)} spec=${hasSpec ? "yes" : "no "}  ${m.question.slice(0, 62)}`,
      );
    }
    for (const s of report.marketSkips) {
      console.log(`  skip      ${s.question.slice(0, 50)} :: ${s.reason}`);
    }
    console.log(`eligible without a research spec: ${report.draftsSkippedNoSpec.length}`);
  } else {
    console.error("usage: cli.ts run|plan [--mode=mock|live] [--live-submit] [--max-drafts=N]");
    process.exit(2);
  }
}

void main();
